import { round, uniqueNumbers } from "./mathEngine";

/**
 * Deterministic question generators.
 *
 * Each template is reproducible from its seed, so the same question can be
 * regenerated by the client, the AI and the attempt history. Templates are
 * intentionally tiny in the skeleton; new generators are added to the registry.
 */

export type GeneratedQuestion = {
  id: string;
  templateKey: string;
  prompt: { en: string; bn: string };
  answer: string;
  options: {
    id: string;
    label: { en: string; bn: string };
    correct: boolean;
  }[];
  explanation: { en: string; bn: string };
  difficulty: number;
  mode: "MCQ" | "TYPED";
  seed: string;
};

export type GeneratorKey =
  | "addition.singleDigit"
  | "addition.twoDigit"
  | "multiplication.singleDigit";

type GeneratorContext = {
  random: () => number;
  difficulty: number;
  mode: "MCQ" | "TYPED";
  seed: string;
};

type GeneratorDefinition = {
  key: GeneratorKey;
  label: { en: string; bn: string };
  generate: (context: GeneratorContext) => {
    prompt: { en: string; bn: string };
    answer: number;
    explanation: { en: string; bn: string };
    mistakes: number[];
  };
};

const createRandom = (seed: string) => {
  let state = 0;
  for (let index = 0; index < seed.length; index += 1) {
    state = (state * 31 + seed.charCodeAt(index)) >>> 0;
  }

  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
};

const between = (random: () => number, min: number, max: number) =>
  Math.floor(random() * (max - min + 1)) + min;

const buildOptions = (
  answer: number,
  mistakes: number[],
  random: () => number,
) => {
  const candidates = uniqueNumbers([
    answer,
    ...mistakes,
    answer + 1,
    answer - 1,
    answer + between(random, 2, 9),
    answer - between(random, 2, 9),
  ]).filter((value) => value >= 0);

  const distractors = candidates
    .filter((value) => value !== answer)
    .slice(0, 3);

  while (distractors.length < 3) {
    const candidate = answer + between(random, 1, 20);
    if (!distractors.includes(candidate)) distractors.push(candidate);
  }

  return [answer, ...distractors]
    .map((value) => ({ value, sort: random() }))
    .sort((a, b) => a.sort - b.sort)
    .map(({ value }, index) => ({
      id: String.fromCharCode(97 + index),
      label: { en: String(value), bn: String(value) },
      correct: value === answer,
    }));
};

const definitions: Record<GeneratorKey, GeneratorDefinition> = {
  "addition.singleDigit": {
    key: "addition.singleDigit",
    label: { en: "Single-digit addition", bn: "এক অঙ্কের যোগ" },
    generate: ({ random }) => {
      const a = between(random, 1, 9);
      const b = between(random, 1, 9);
      return {
        prompt: {
          en: `${a} + ${b} = ?`,
          bn: `${a} + ${b} = ?`,
        },
        answer: a + b,
        explanation: {
          en: `Count on from ${a}: ${Array.from(
            { length: b },
            (_, index) => a + index + 1,
          ).join(", ")}. So ${a} + ${b} = ${a + b}.`,
          bn: `${a} থেকে ${b} ধাপ গুনুন: ${a + b}।`,
        },
        mistakes: [a + b - 1, a + b + 1, a * b],
      };
    },
  },
  "addition.twoDigit": {
    key: "addition.twoDigit",
    label: { en: "Two-digit addition", bn: "দুই অঙ্কের যোগ" },
    generate: ({ random }) => {
      const a = between(random, 10, 49);
      const b = between(random, 10, 49);
      const forgotCarry =
        (a % 10) + (b % 10) + (Math.floor(a / 10) + Math.floor(b / 10)) * 10;
      return {
        prompt: {
          en: `${a} + ${b} = ?`,
          bn: `${a} + ${b} = ?`,
        },
        answer: a + b,
        explanation: {
          en: `Add the ones: ${a % 10} + ${b % 10}. Carry if needed, then add the tens.`,
          bn: `একক স্থান যোগ করুন: ${a % 10} + ${b % 10}। প্রয়োজনে হাতে রাখুন, তারপর দশক যোগ করুন।`,
        },
        mistakes: [forgotCarry, a + b - 10, a + b + 10],
      };
    },
  },
  "multiplication.singleDigit": {
    key: "multiplication.singleDigit",
    label: { en: "Single-digit multiplication", bn: "এক অঙ্কের গুণ" },
    generate: ({ random }) => {
      const a = between(random, 2, 9);
      const b = between(random, 2, 9);
      return {
        prompt: {
          en: `${a} × ${b} = ?`,
          bn: `${a} × ${b} = ?`,
        },
        answer: a * b,
        explanation: {
          en: `${a} groups of ${b} make ${a * b}.`,
          bn: `${a} টি ${b} এর দলে মোট ${a * b}।`,
        },
        mistakes: [a + b, a * b - a, a * b + b],
      };
    },
  },
};

export const GENERATOR_KEYS = Object.keys(definitions) as GeneratorKey[];

export const isGeneratorKey = (value: string): value is GeneratorKey =>
  value in definitions;

export const generateQuestion = (options: {
  generator: GeneratorKey;
  difficulty?: number;
  mode?: "MCQ" | "TYPED";
  seed?: string;
}): GeneratedQuestion => {
  const seed =
    options.seed ||
    `${options.generator}:${Date.now().toString(36)}:${Math.random()
      .toString(36)
      .slice(2, 8)}`;

  const definition = definitions[options.generator];
  const random = createRandom(seed);
  const mode = options.mode ?? "MCQ";
  const generated = definition.generate({
    random,
    difficulty: options.difficulty ?? 1,
    mode,
    seed,
  });

  const options_ = buildOptions(generated.answer, generated.mistakes, random);

  return {
    id: `${options.generator}-${seed.slice(-8)}`,
    templateKey: definition.key,
    prompt: generated.prompt,
    answer: String(round(generated.answer, 4)),
    options: mode === "MCQ" ? options_ : [],
    explanation: generated.explanation,
    difficulty: options.difficulty ?? 1,
    mode,
    seed,
  };
};

export const generateQuestionSet = (options: {
  generator: GeneratorKey;
  count: number;
  difficulty?: number;
  mode?: "MCQ" | "TYPED";
  seed?: string;
}) => {
  const baseSeed = options.seed || Date.now().toString(36);
  return Array.from(
    { length: Math.min(Math.max(options.count, 1), 50) },
    (_, index) =>
      generateQuestion({
        generator: options.generator,
        difficulty: options.difficulty,
        mode: options.mode,
        seed: `${baseSeed}-${index}`,
      }),
  );
};
